import{_ as t,o,c as r,a2 as a}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"OIDC Federation Dogfood — dcr-flow quality report","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/auth/oidc-federation-dcr.md","filePath":"quality-reports/auth/oidc-federation-dcr.md"}'),d={name:"quality-reports/auth/oidc-federation-dcr.md"};function s(i,e,c,n,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="oidc-federation-dogfood-—-dcr-flow-quality-report" tabindex="-1">OIDC Federation Dogfood — dcr-flow quality report <a class="header-anchor" href="#oidc-federation-dogfood-—-dcr-flow-quality-report" aria-label="Permalink to &quot;OIDC Federation Dogfood — dcr-flow quality report&quot;">​</a></h1><p>DCR-layer report for <code>examples/dogfood-oidc-federation</code> Sub-Issue #873 (v1.21-4b). Extends the skeleton report (<code>oidc-federation-discovery.md</code>, Sub-Issue #872) with the RFC 7591 Dynamic Client Registration fidelity harness. Sub-Issues #874 (id_token verification) + #875 (Federation trust chain + rotation e2e) layer the remaining fidelity axes on top.</p><h2 id="fidelity-axes-dcr-flow" tabindex="-1">Fidelity axes (dcr-flow) <a class="header-anchor" href="#fidelity-axes-dcr-flow" aria-label="Permalink to &quot;Fidelity axes (dcr-flow)&quot;">​</a></h2><p>The dcr-flow harness lifts the skeleton&#39;s 4 axes to 8. Axes 1–4 stay covered by the Sub-Issue #872 skeleton report (<code>discovery-jwks-skeleton.spec.ts</code>, 25 tests); axes 5–8 are the DCR-layer additions this Sub-Issue lands.</p><table tabindex="0"><thead><tr><th>axis</th><th>mock (<code>@kiwa-test/auth</code> via <code>src/lib/dcr.ts</code> wrapper)</th><th>real (Keycloak + testcontainers, <code>OIDC_BOOTSTRAP=1</code>)</th><th>assertion</th></tr></thead><tbody><tr><td>5. auth method 3 shapes</td><td><code>client_secret_basic</code> + <code>client_secret_post</code> mint a <code>client_secret</code>; <code>pk_jwt</code> requires <code>jwks_uri</code> or inline <code>jwks</code>, omits <code>client_secret</code>, and echoes the requested method verbatim on the response. Unknown methods refuse with <code>errorKind=unsupported_auth_method</code>.</td><td>Keycloak <code>/registrations</code> accepts the same three methods; <code>pk_jwt</code> maps to Keycloak&#39;s <code>client_jwt</code> policy with the RP&#39;s JWKS registered as the client authenticator.</td><td>RFC 7591 §2 — <code>token_endpoint_auth_method</code> must be one advertised by the OP&#39;s Discovery metadata; JWT-based methods require a JWKS source.</td></tr><tr><td>6. dropped grant refusal</td><td><code>password</code> / <code>implicit</code> / <code>client_credentials</code> refuse at the wrapper before delegating to the underlying kiwa library. Mixed allowlist (<code>authorization_code + password</code>) refuses partially. <code>authorization_code + refresh_token</code> accepts.</td><td>Keycloak refuses the same three grants at realm boot when OAuth 2.1 compliance is enabled.</td><td>OAuth 2.1 §1 — grant types the spec dropped MUST NOT be registered on new clients.</td></tr><tr><td>7. software_statement JWS</td><td>Verified signature (via <code>mintSoftwareStatement(claims, TRUST_ANCHOR)</code> + matching <code>softwareStatementTrustAnchor</code>) accepts the registration + annotates the trace as <code>software_statement=verified</code>. Tampered signature refuses with <code>errorKind=invalid_software_statement</code>. Malformed JWT refuses. Statement supplied without a configured trust anchor refuses.</td><td>Keycloak verifies <code>software_statement</code> via the configured <code>software_statement_key</code> on the realm.</td><td>RFC 7591 §2.3 — the AS MAY refuse a registration whose <code>software_statement</code> signature does not verify. The dogfood layer enforces MAY as MUST for the fidelity harness.</td></tr><tr><td>8. redirect_uris validation</td><td>Missing / empty <code>redirect_uris</code> refuses. Non-URL entries refuse (URL constructor throws). Partial mix (<code>valid + garbage</code>) refuses. Multiple valid URLs echo verbatim on the response.</td><td>Keycloak refuses on the same conditions.</td><td>RFC 7591 §2 — <code>redirect_uris</code> is mandatory + every entry MUST be a valid URL.</td></tr></tbody></table><h2 id="test-coverage" tabindex="-1">Test coverage <a class="header-anchor" href="#test-coverage" aria-label="Permalink to &quot;Test coverage&quot;">​</a></h2><ul><li><code>tests/dcr-flow.spec.ts</code> — 23 tests, split into five describe blocks: <ul><li><code>axis 5 — DCR auth method 3 shapes</code> — 6 tests covering <code>client_secret_basic</code> / <code>client_secret_post</code> / <code>pk_jwt</code> accept paths, <code>pk_jwt</code> without JWKS source refuse, unknown method refuse, real env-missing refuse.</li><li><code>axis 6 — OAuth 2.1 dropped grant refusal</code> — 5 tests covering <code>password</code> / <code>implicit</code> / <code>client_credentials</code> refuse, mixed allowlist + dropped grant partial refuse, <code>authorization_code + refresh_token</code> accept.</li><li><code>axis 7 — software_statement JWS verification</code> — 4 tests covering valid signature accept + trace annotation, tampered signature refuse, malformed JWT refuse, missing trust anchor refuse.</li><li><code>axis 8 — redirect_uris validation</code> — 5 tests covering missing / empty / non-URL / partial mix refuse + multiple valid URLs accept.</li><li><code>DCR-flow HTTP layer (Hono /register)</code> — 3 tests covering <code>pk_jwt</code> over HTTP (201 + omitted <code>client_secret</code>), dropped grant over HTTP (400 + <code>invalid_client_metadata</code>), real env-missing over HTTP (503).</li></ul></li></ul><p>Behavioural coverage on the underlying <code>dynamicClientRegistration</code> helper lives inside <code>packages/auth/tests/setup-oidc-env.test.ts</code> (35 tests per PR #855). This report tracks the wrapper layer + fidelity harness; the shared library retains its own coverage numbers.</p><h2 id="wrapper-contract" tabindex="-1">Wrapper contract <a class="header-anchor" href="#wrapper-contract" aria-label="Permalink to &quot;Wrapper contract&quot;">​</a></h2><p>The dogfood-specific behaviour lives entirely in <code>src/lib/dcr.ts</code> (<code>handleRegistration</code>). The wrapper receives the raw request, runs the four fidelity checks, translates <code>pk_jwt</code> → <code>none</code> before delegating to the underlying kiwa <code>env.registerClient</code>, and echoes the requested <code>token_endpoint_auth_method</code> on the response so the caller observes the dogfood-layer method verbatim.</p><p>Trace annotations emitted by the wrapper —</p><ul><li><code>detail.auth_method</code> — populated on both success + failure so downstream tests can pin the requested method.</li><li><code>detail.software_statement</code> — <code>verified</code> on the accept path, <code>refused</code> when the underlying library rejects a bad signature.</li><li><code>errorKind</code> — kebab-case tag (<code>invalid_redirect_uris</code> / <code>unsupported_auth_method</code> / <code>dropped_grant_type</code> / <code>invalid_jwks_source</code> / <code>invalid_software_statement</code> / <code>unsupported_grant_type</code> / <code>unsupported_response_type</code> / <code>unknown_error</code>) so tests can distinguish refusal surfaces without regexing the underlying exception.</li></ul><h2 id="environment-gating" tabindex="-1">Environment gating <a class="header-anchor" href="#environment-gating" aria-label="Permalink to &quot;Environment gating&quot;">​</a></h2><ul><li><code>KIWA_MODE=mock</code> — forces the mock adapter; every axis 5–8 test always runs.</li><li><code>OIDC_BOOTSTRAP=1</code> — opt-in for real ceremonies. Sub-Issue #874&#39;s Keycloak wiring covers axis 5–8 against Keycloak <code>/registrations</code>; until then the real adapter refuses every <code>registerClient</code> call with <code>KIWA_OIDC_ENV_MISSING</code>.</li><li>Without <code>OIDC_BOOTSTRAP=1</code>, the four real-driver refusal tests (one per axis, plus the HTTP-layer real test) prove the wrapper surfaces the env-missing state uniformly at the API + HTTP boundary.</li></ul><h2 id="what-lands-in-the-successors" tabindex="-1">What lands in the successors <a class="header-anchor" href="#what-lands-in-the-successors" aria-label="Permalink to &quot;What lands in the successors&quot;">​</a></h2><ul><li><strong>Sub-Issue #874 (v1.21-4c — id_token)</strong> lands the Nuxt 3 RP + authorization code flow + id_token verify (JWS + claims + nonce + hash chain). Fidelity harness grows to 12 axes (axes 5–8 stay, axes 9–12 layer id_token verification, at_hash / c_hash, nonce, clock-skew tolerance).</li><li><strong>Sub-Issue #875 (v1.21-4d — Federation + rotation e2e)</strong> lands the trust chain (3-level resolve + cycle detect + expiry) + JWKS rotation e2e (id_token signed under old kid stays verifiable until retention window elapses) + real Keycloak fidelity gate + integrated docs. Fidelity harness caps out at 16 axes.</li></ul>',16)])])}const f=t(d,[["render",s]]);export{p as __pageData,f as default};
